def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    for c in range(w):
        if g[h - 1][c] != 5:
            continue

        seeds = [(r, g[r][c]) for r in range(h - 1) if g[r][c] != 0]
        if not seeds:
            continue

        # Extend the first seed to the top.
        for r in range(seeds[0][0]):
            g[r][c] = seeds[0][1]

        # Between successive seeds, fill blanks with the lower seed's color.
        for (ra, _), (rb, cb) in zip(seeds, seeds[1:]):
            for r in range(ra + 1, rb):
                g[r][c] = cb

        # The bottom marker's 5 fills the space below the final seed.
        last = seeds[-1][0]
        for r in range(last + 1, h):
            g[r][c] = 5
    return g
